kroppar_per_varv:
trigReset(CLK := SYS_RESET);

(* Nodstopp eller spanningspaslag kraver ny stigande flank pa SYS_RESET *)
IF NOT EMG_OK THEN
    xKravOmstart := TRUE;
END_IF;
IF trigReset.Q AND EMG_OK THEN
    xKravOmstart := FALSE;
    xLarm := FALSE;
END_IF;

(* Driftsklar-villkor: bara lasning av sakerhets-PLC:n, ingen egen sakerhetsfunktion *)
xDriftsklar := EMG_OK AND AIR_OK AND SYS_AUTO AND NOT xKravOmstart AND NOT xLarm;

(* Kvittensvakt: 3,0 s nominellt, larmar mellan 2,8 s och 3,4 s efter flanken pa REQ *)
tmrAck(IN := ST310_HSK_REQ AND NOT ST310_HSK_ACK, PT := T#3S);
IF tmrAck.Q THEN
    xLarm := TRUE;
END_IF;

(* Gripkraftsvakt, galler hela tiden ST320 haller detaljen *)
IF ST320_GRP_CLOSED AND ((ST320_GRP_FRC < 40.0) OR (ST320_GRP_FRC > 260.0)) THEN
    xLarm := TRUE;
END_IF;

(* Omsesidig uteslutning, bade av vakt har och av sjalva stegkedjan *)
IF ST310_RB_START AND ST320_RB_START THEN
    ST310_RB_START := FALSE;
    ST320_RB_START := FALSE;
    xLarm := TRUE;
END_IF;

(* Greppordning: ST310 far aldrig oppna innan ST320 haller *)
IF ST310_GRP_OPEN AND NOT ST320_GRP_CLOSED THEN
    ST310_GRP_OPEN := FALSE;
    xLarm := TRUE;
END_IF;

SYS_ALARM := xLarm;

(* Larm eller ej driftsklar: bada robotarna stannar dar de ar *)
IF xLarm OR NOT xDriftsklar THEN
    ST310_RB_START := FALSE;
    ST320_RB_START := FALSE;
ELSE
    CASE steg OF

        0: (* vanta pa detalj i gripdon och fri zon *)
            IF ST310_PRT_PRS AND ST310_ZON_FREE THEN
                ST310_RB_START := TRUE;
                steg := 10;
            END_IF;

        10: (* ST310 pa vag till overlamningslaget *)
            IF ST310_RB_DONE THEN
                ST310_RB_START := FALSE;
                ST310_HSK_REQ := TRUE;
                steg := 20;
            END_IF;

        20: (* vantar pa ST320:s kvittens *)
            IF ST310_HSK_ACK AND ST310_ZON_FREE AND NOT ST310_RB_START THEN
                ST320_RB_START := TRUE;
                steg := 30;
            END_IF;

        30: (* ST320 pa vag till overlamningslaget *)
            IF ST320_RB_DONE THEN
                ST320_RB_START := FALSE;
                ST320_GRP_CLOSE := TRUE;
                steg := 40;
            END_IF;

        40: (* vantar pa att ST320 grepper detaljen med giltig kraft *)
            IF ST320_GRP_CLOSED THEN
                ST320_GRP_CLOSE := FALSE;
                IF (ST320_GRP_FRC >= 40.0) AND (ST320_GRP_FRC <= 260.0) THEN
                    ST310_GRP_OPEN := TRUE;
                    steg := 50;
                ELSE
                    xLarm := TRUE;
                END_IF;
            END_IF;

        50: (* vantar pa att ST310 slappt och anmalt klart *)
            IF ST310_GRP_OPENED AND ST310_HSK_DONE THEN
                ST310_HSK_REQ := FALSE;
                ST310_HSK_RST := TRUE;
                ST310_GRP_OPEN := FALSE;
                steg := 60;
            END_IF;

        60: (* aterstall handskakningen mot ST320 *)
            IF NOT ST310_HSK_ACK THEN
                ST310_HSK_RST := FALSE;
                steg := 0;
            END_IF;

        ELSE
            steg := 0;
    END_CASE;
END_IF;

(* --- reset och sakerhetsforregling, bara laser EMG_OK --- *)
trigReset(CLK := SYS_RESET);
IF NOT EMG_OK THEN
    xKravOmstart := TRUE;
    steg := 0;
END_IF;
IF trigReset.Q AND EMG_OK THEN
    xKravOmstart := FALSE;
    xLarm := FALSE;
    steg := 0;
END_IF;

xDriftsklar := EMG_OK AND AIR_OK AND SYS_AUTO AND NOT xKravOmstart;
xEnable := xDriftsklar AND ST310_ZON_FREE AND NOT xLarm;

(* --- kvittensvakt, 3,0 s fran att REQ gick hog --- *)
tmrAck(IN := (steg = 2), PT := T#3.0S);
IF tmrAck.Q THEN
    xLarm := TRUE;
END_IF;

(* --- gripkraftsvakt, kontinuerlig medan mottagaren haller grepp --- *)
IF ST320_GRP_CLOSED AND (ST320_GRP_FRC < 40.0 OR ST320_GRP_FRC > 260.0) THEN
    xLarm := TRUE;
END_IF;

(* --- sekvens --- *)
CASE steg OF
    0:
        IF xEnable AND ST310_PRT_PRS THEN
            steg := 1;
        END_IF;

    1:
        IF ST310_RB_DONE THEN
            steg := 2;
        END_IF;

    2:
        IF ST310_HSK_ACK THEN
            steg := 3;
        END_IF;

    3:
        IF ST320_RB_DONE THEN
            steg := 4;
        END_IF;

    4:
        IF ST320_GRP_CLOSED AND ST320_GRP_FRC >= 40.0 AND ST320_GRP_FRC <= 260.0 THEN
            steg := 5;
        END_IF;

    5:
        IF ST310_GRP_OPENED AND ST310_HSK_DONE THEN
            steg := 6;
        END_IF;

    6:
        IF NOT ST310_HSK_ACK THEN
            steg := 0;
        END_IF;
END_CASE;

(* --- utgangar, varje utgang skrivs pa exakt ett stalle --- *)
ST310_RB_START := (steg = 1) AND xEnable;
ST320_RB_START := (steg = 3) AND xEnable;
ST310_HSK_REQ := (steg >= 2) AND (steg <= 5) AND xEnable;
ST320_GRP_CLOSE := (steg >= 4) AND xEnable;
ST310_GRP_OPEN := (steg >= 5) AND xEnable AND ST320_GRP_CLOSED;
ST310_HSK_RST := (steg = 6) AND xEnable;
SYS_ALARM := xLarm;

(* VC_ASSIST KROPP BORJAR *)
trigReset(CLK := SYS_RESET);
IF trigReset.Q THEN
    xKravOmstart := FALSE;
    xLarm := FALSE;
    SYS_ALARM := FALSE;
END_IF;

IF NOT EMG_OK THEN
    xKravOmstart := TRUE;
    xLarm := TRUE;
END_IF;

xDriftsklar := EMG_OK AND AIR_OK AND SYS_AUTO AND NOT xKravOmstart AND NOT xLarm;

(* Kvittensvakt: fordrojning fran HSK_REQ till HSK_ACK *)
tmrAck(IN := (steg = 2), PT := T#3.0S);
IF tmrAck.Q AND NOT ST310_HSK_ACK THEN
    xLarm := TRUE;
END_IF;

(* Gripkraft *)
IF ST320_GRP_CLOSED AND (ST320_GRP_FRC < 40.0 OR ST320_GRP_FRC > 260.0) THEN
    xLarm := TRUE;
END_IF;

(* Omsesidig uteslutning som sakerhetsnat, utover sekvensen *)
IF ST310_RB_START AND ST320_RB_START THEN
    xLarm := TRUE;
END_IF;

IF xLarm THEN
    SYS_ALARM := TRUE;
    ST310_RB_START := FALSE;
    ST320_RB_START := FALSE;
ELSE
    CASE steg OF
        0:
            ST310_HSK_REQ := FALSE;
            ST310_HSK_RST := FALSE;
            ST320_GRP_CLOSE := FALSE;
            ST310_GRP_OPEN := FALSE;
            IF xDriftsklar AND ST310_ZON_FREE AND ST310_PRT_PRS THEN
                ST310_RB_START := TRUE;
                steg := 1;
            END_IF;

        1:
            IF ST310_RB_DONE THEN
                ST310_RB_START := FALSE;
                ST310_HSK_REQ := TRUE;
                steg := 2;
            END_IF;

        2:
            IF ST310_HSK_ACK THEN
                IF xDriftsklar AND ST310_ZON_FREE THEN
                    ST320_RB_START := TRUE;
                    steg := 3;
                END_IF;
            END_IF;

        3:
            IF ST320_RB_DONE THEN
                ST320_RB_START := FALSE;
                ST320_GRP_CLOSE := TRUE;
                steg := 4;
            END_IF;

        4:
            IF ST320_GRP_CLOSED THEN
                ST310_GRP_OPEN := TRUE;
                steg := 5;
            END_IF;

        5:
            IF ST310_GRP_OPENED AND ST310_HSK_DONE THEN
                ST310_HSK_REQ := FALSE;
                ST310_HSK_RST := TRUE;
                steg := 6;
            END_IF;

        6:
            IF NOT ST310_HSK_ACK THEN
                ST310_HSK_RST := FALSE;
                ST310_GRP_OPEN := FALSE;
                ST320_GRP_CLOSE := FALSE;
                steg := 0;
            END_IF;
    END_CASE;
END_IF;
(* VC_ASSIST KROPP SLUTAR *)

trigReset(CLK := SYS_RESET);
IF trigReset.Q THEN
    xKravOmstart := FALSE;
END_IF;
IF NOT EMG_OK THEN
    xKravOmstart := TRUE;
END_IF;
IF trigReset.Q THEN
    xLarm := FALSE;
END_IF;

xDriftsklar := EMG_OK AND AIR_OK AND SYS_AUTO AND NOT xKravOmstart AND NOT xLarm;

tmrAck(IN := ST310_HSK_REQ AND NOT ST310_HSK_ACK, PT := T#3.0S);
IF tmrAck.Q THEN
    xLarm := TRUE;
END_IF;

IF ST320_GRP_CLOSED AND (ST320_GRP_FRC < 40.0 OR ST320_GRP_FRC > 260.0) THEN
    xLarm := TRUE;
END_IF;

CASE steg OF
    0:
        IF xDriftsklar AND ST310_ZON_FREE AND ST310_PRT_PRS THEN
            ST310_RB_START := TRUE;
            steg := 1;
        END_IF;

    1:
        IF ST310_RB_DONE THEN
            ST310_RB_START := FALSE;
            ST310_HSK_REQ := TRUE;
            steg := 2;
        END_IF;

    2:
        IF ST310_HSK_ACK AND xDriftsklar AND ST310_ZON_FREE THEN
            ST320_RB_START := TRUE;
            steg := 3;
        END_IF;

    3:
        IF ST320_RB_DONE THEN
            ST320_RB_START := FALSE;
            ST320_GRP_CLOSE := TRUE;
            steg := 4;
        END_IF;

    4:
        IF ST320_GRP_CLOSED THEN
            ST310_GRP_OPEN := TRUE;
            steg := 5;
        END_IF;

    5:
        IF ST310_GRP_OPENED AND ST310_HSK_DONE THEN
            ST310_HSK_REQ := FALSE;
            ST310_HSK_RST := TRUE;
            steg := 6;
        END_IF;

    6:
        IF NOT ST310_HSK_ACK THEN
            ST310_HSK_RST := FALSE;
            steg := 7;
        END_IF;

    7:
        ST320_GRP_CLOSE := FALSE;
        ST310_GRP_OPEN := FALSE;
        steg := 0;

    ELSE
        steg := 0;
END_CASE;

IF ST310_RB_START AND ST320_RB_START THEN
    ST310_RB_START := FALSE;
    ST320_RB_START := FALSE;
    xLarm := TRUE;
END_IF;

IF ST310_GRP_OPEN AND NOT ST320_GRP_CLOSED THEN
    ST310_GRP_OPEN := FALSE;
    xLarm := TRUE;
END_IF;

IF NOT xDriftsklar THEN
    ST310_RB_START := FALSE;
    ST320_RB_START := FALSE;
END_IF;

SYS_ALARM := xLarm;

(* --- Reset- och driftlagesspark --- *)
trigReset(CLK := SYS_RESET);

IF NOT EMG_OK THEN
    xKravOmstart := TRUE;
END_IF;

IF trigReset.Q AND EMG_OK THEN
    xKravOmstart := FALSE;
    xLarm := FALSE;
    SYS_ALARM := FALSE;
    steg := 0;
END_IF;

xAuto := SYS_AUTO AND EMG_OK AND AIR_OK AND NOT xKravOmstart AND NOT xLarm;
xHand := NOT SYS_AUTO AND EMG_OK AND AIR_OK AND NOT xKravOmstart AND NOT xLarm;

(* --- Handkorning, hall-for-att-kora, bara uppat --- *)
IF xHand AND ST260_MAN_JOG AND NOT ST260_LFT_TOP THEN
    ST260_LFT_UP := TRUE;
ELSE
    ST260_LFT_UP := FALSE;
END_IF;

(* --- Automatisk palleteringssekvens --- *)
IF NOT xAuto THEN
    steg := 0;
    ST260_RB_START := FALSE;
    ST260_VAC_ON := FALSE;
    ST260_LFT_DOWN := FALSE;
ELSE
    CASE steg OF
        0:
            ST260_RB_START := FALSE;
            IF ST260_PRT_PRS AND ST260_LAY_CNT < 5 THEN
                ST260_RB_START := TRUE;
                steg := 1;
            END_IF;

        1:
            IF ST260_RB_DONE THEN
                ST260_RB_START := FALSE;
                ST260_VAC_ON := TRUE;
                steg := 2;
            END_IF;

        2:
            IF ST260_VAC_OK THEN
                ST260_VAC_ON := FALSE;
                ST260_LFT_DOWN := TRUE;
                steg := 3;
            END_IF;

        3:
            IF ST260_LFT_BOT THEN
                ST260_LFT_DOWN := FALSE;
                steg := 0;
            END_IF;
    END_CASE;
END_IF;

(* --- Omsesidig uteslutning, sista skyddet mot kortslutning i lyftbordets kontaktorer --- *)
IF ST260_LFT_UP AND ST260_LFT_DOWN THEN
    ST260_LFT_UP := FALSE;
    ST260_LFT_DOWN := FALSE;
    xLarm := TRUE;
END_IF;

(* --- Vakuumovervakning, grepp slappt eller sugkopp fastsugen --- *)
IF ST260_VAC_ON AND (ST260_VAC_PRS < 40.0 OR ST260_VAC_PRS > 85.0) THEN
    xLarm := TRUE;
END_IF;

(* --- Tidsovervakning av lyftrorelsen, andlage ska nas inom 4,0 s --- *)
xLyftRor := (ST260_LFT_UP AND NOT ST260_LFT_TOP) OR (ST260_LFT_DOWN AND NOT ST260_LFT_BOT);
tmrLyft(IN := xLyftRor, PT := T#4.0S);
IF tmrLyft.Q THEN
    xLarm := TRUE;
END_IF;

(* --- Samlingslarm, latchat. Kravs flank pa SYS_RESET for kvittering --- *)
IF xLarm THEN
    SYS_ALARM := TRUE;
    ST260_RB_START := FALSE;
    ST260_VAC_ON := FALSE;
    ST260_LFT_UP := FALSE;
    ST260_LFT_DOWN := FALSE;
    steg := 0;
END_IF;

trigReset(CLK := SYS_RESET);

(* krav pa flank pa SYS_RESET efter spanningspaslag och nodstopp *)
IF NOT EMG_OK THEN
    xKravOmstart := TRUE;
    steg := 0;
END_IF
IF trigReset.Q AND EMG_OK THEN
    xKravOmstart := FALSE;
    xLarm := FALSE;
END_IF

(* lagesvaljare, ombesidigt uteslutande *)
xAuto := SYS_AUTO AND EMG_OK AND AIR_OK AND NOT xLarm AND NOT xKravOmstart;
xHand := NOT SYS_AUTO AND EMG_OK AND AIR_OK AND NOT xLarm AND NOT xKravOmstart;

(* automatikens stegkedja *)
IF xAuto THEN
    CASE steg OF
        0: IF ST260_PRT_PRS AND ST260_LAY_CNT < 5 THEN
               steg := 1;
           END_IF
        1: IF ST260_RB_DONE THEN
               steg := 2;
           END_IF
        2: IF ST260_VAC_OK THEN
               steg := 3;
           END_IF
        3: IF ST260_LFT_BOT THEN
               steg := 0;
           END_IF
    ELSE
        steg := 0;
    END_CASE
ELSE
    steg := 0;
END_IF

(* varje utgang skrivs pa exakt ett stalle *)
ST260_RB_START  := xAuto AND (steg = 1);
ST260_VAC_ON    := xAuto AND (steg = 2);
ST260_LFT_DOWN  := xAuto AND (steg = 3);
ST260_LFT_UP    := xHand AND ST260_MAN_JOG AND NOT ST260_LFT_TOP;

(* tidsovervakning av lyftbordets rorelse, 4,0 s +-0,2..0,4 s *)
xLyftRor := ST260_LFT_UP OR ST260_LFT_DOWN;
tmrLyft(IN := xLyftRor, PT := T#4s0ms);

(* larmvillkor samlas och latchas i en enda skrivning till SYS_ALARM *)
IF (xLyftRor AND tmrLyft.Q)
   OR (ST260_VAC_ON AND (ST260_VAC_PRS < 40.0 OR ST260_VAC_PRS > 85.0)) THEN
    xLarm := TRUE;
END_IF
SYS_ALARM := xLarm;

xAuto := SYS_AUTO;
xHand := NOT SYS_AUTO;

(* Flank pa aterstallning *)
trigReset(CLK := SYS_RESET);

(* Krav pa omstart efter spanningspaslag / nodstopp *)
IF NOT EMG_OK THEN
    xKravOmstart := TRUE;
END_IF;
IF trigReset.Q AND EMG_OK THEN
    xKravOmstart := FALSE;
    xLarm := FALSE;
    steg := 0;
END_IF;

(* Vakuumovervakning *)
IF ST260_VAC_ON AND (ST260_VAC_PRS < 40.0 OR ST260_VAC_PRS > 85.0) THEN
    xLarm := TRUE;
END_IF;

(* Tidsovervakning lyftbord: andlage kravs inom 4,0 s efter kommando *)
xLyftRor := ST260_LFT_UP OR ST260_LFT_DOWN;
tmrLyft(IN := xLyftRor AND NOT ((ST260_LFT_UP AND ST260_LFT_TOP) OR (ST260_LFT_DOWN AND ST260_LFT_BOT)),
        PT := T#4S0MS);
IF tmrLyft.Q THEN
    xLarm := TRUE;
END_IF;

(* Default: alla rorelser/kommandon av, byggs upp nedan om inget larm *)
ST260_RB_START := FALSE;
ST260_VAC_ON   := FALSE;
ST260_LFT_DOWN := FALSE;
ST260_LFT_UP   := FALSE;

IF xLarm THEN
    (* Ett larm ska stanna cellen helt i samma scan, inget lyft far lamnas i rorelse *)
    steg := 0;
    SYS_ALARM := TRUE;
ELSE
    SYS_ALARM := FALSE;

    IF xAuto AND EMG_OK AND AIR_OK AND NOT xKravOmstart THEN
        CASE steg OF
            0:
                IF ST260_PRT_PRS AND ST260_LAY_CNT < 5 THEN
                    ST260_RB_START := TRUE;
                    steg := 1;
                END_IF;

            1:
                ST260_RB_START := TRUE;
                IF ST260_RB_DONE THEN
                    ST260_RB_START := FALSE;
                    ST260_VAC_ON := TRUE;
                    steg := 2;
                END_IF;

            2:
                ST260_VAC_ON := TRUE;
                IF ST260_VAC_OK THEN
                    ST260_VAC_ON := FALSE;
                    steg := 3;
                END_IF;

            3:
                ST260_LFT_DOWN := TRUE;
                IF ST260_LFT_BOT THEN
                    ST260_LFT_DOWN := FALSE;
                    steg := 0;
                END_IF;
        END_CASE;

    ELSIF xHand AND EMG_OK THEN
        (* Handkorning: hall-for-att-kora, bara uppat, stannar vid ovre andlage *)
        IF ST260_MAN_JOG AND NOT ST260_LFT_TOP THEN
            ST260_LFT_UP := TRUE;
        END_IF;
    END_IF;
END_IF;

(* Ovanpaliggande sakerhet: LFT_UP och LFT_DOWN far aldrig vara hoga samtidigt *)
IF ST260_LFT_DOWN THEN
    ST260_LFT_UP := FALSE;
END_IF;

IF NOT EMG_OK THEN
    xKravOmstart := TRUE;
END_IF;

trigReset(CLK := SYS_RESET);
IF trigReset.Q THEN
    xKravOmstart := FALSE;
    xLarm := FALSE;
END_IF;

IF ST260_VAC_ON AND (ST260_VAC_PRS < 40.0 OR ST260_VAC_PRS > 85.0) THEN
    xLarm := TRUE;
END_IF;

xLyftRor := ST260_LFT_UP OR ST260_LFT_DOWN;
tmrLyft(IN := xLyftRor, PT := T#4S0MS);
IF tmrLyft.Q AND NOT (ST260_LFT_TOP OR ST260_LFT_BOT) THEN
    xLarm := TRUE;
END_IF;

SYS_ALARM := xLarm;

(* xAuto/xHand = respektive lage, spardt och friskrivet fran larm/nodstopp/reset *)
xAuto := SYS_AUTO AND EMG_OK AND AIR_OK AND NOT xKravOmstart AND NOT xLarm;
xHand := (NOT SYS_AUTO) AND EMG_OK AND AIR_OK AND NOT xKravOmstart AND NOT xLarm;

IF NOT xAuto THEN
    steg := 0;
    ST260_RB_START := FALSE;
    ST260_VAC_ON := FALSE;
ELSE
    CASE steg OF
        0:
            IF ST260_RB_DONE THEN
                ST260_RB_START := FALSE;
                ST260_VAC_ON := TRUE;
                steg := 1;
            ELSIF ST260_PRT_PRS AND (ST260_LAY_CNT < 5) THEN
                ST260_RB_START := TRUE;
            ELSE
                ST260_RB_START := FALSE;
            END_IF;
        1:
            IF ST260_VAC_OK THEN
                ST260_VAC_ON := FALSE;
                steg := 2;
            END_IF;
        2:
            IF ST260_LFT_BOT THEN
                steg := 0;
            END_IF;
    END_CASE;
END_IF;

(* enda skrivningen av respektive lyftutgang, aldrig samtidigt eftersom xAuto/xHand ar omsesidigt uteslutande *)
ST260_LFT_DOWN := xAuto AND (steg = 2) AND NOT ST260_LFT_BOT;
ST260_LFT_UP := xHand AND ST260_MAN_JOG AND NOT ST260_LFT_TOP;

(* mät höjd/omradeskoll *)
xOmradeOk := (ST200_HGT_MM >= 0.0) AND (ST200_HGT_MM <= 250.0);

(* maskinfel latchas, nollstalls bara via CLEAR i ABORTED nar orsaken ar borta *)
IF (NOT EMG_OK) OR (NOT xOmradeOk) THEN
    xMaskinfel := TRUE;
END_IF;

trigSc(CLK := ST200_PML_SC);

kmd := ST200_PML_CMD;

IF xMaskinfel AND (tillstand <> 8) AND (tillstand <> 9) THEN
    (* maskinfel tar over oavsett tillstand och kommando, aldrig genvag - alltid via ABORTING *)
    tillstand := 8;
ELSE
    CASE kmd OF
        1: (* Reset *)
            IF (tillstand = 2) OR (tillstand = 17) THEN
                tillstand := 15;
            END_IF;
        2: (* Start *)
            IF tillstand = 4 THEN
                tillstand := 3;
            END_IF;
        3: (* Stop *)
            IF (tillstand <> 1) AND (tillstand <> 2) AND (tillstand <> 7) AND (tillstand <> 8) AND (tillstand <> 9) THEN
                tillstand := 7;
            END_IF;
        4: (* Hold *)
            IF tillstand = 6 THEN
                tillstand := 10;
            END_IF;
        5: (* Unhold *)
            IF tillstand = 11 THEN
                tillstand := 12;
            END_IF;
        6: (* Suspend *)
            IF tillstand = 6 THEN
                tillstand := 13;
            END_IF;
        7: (* Unsuspend *)
            IF tillstand = 5 THEN
                tillstand := 14;
            END_IF;
        8: (* Abort, giltig i alla tillstand utom ABORTING/ABORTED *)
            IF (tillstand <> 8) AND (tillstand <> 9) THEN
                tillstand := 8;
            END_IF;
        9: (* Clear, enda vagen ut ur ABORTED, kraver att orsaken ar borta *)
            IF tillstand = 9 THEN
                IF EMG_OK AND xOmradeOk THEN
                    tillstand := 1;
                    xMaskinfel := FALSE;
                END_IF;
            END_IF;
    ELSE
        ; (* 0, 10.. eller ogiltigt kommando i detta tillstand: ignoreras *)
    END_CASE;

    IF trigSc.Q THEN
        CASE tillstand OF
            15: tillstand := 4;  (* Resetting -> Idle *)
            3:  tillstand := 6;  (* Starting -> Execute *)
            6:  tillstand := 16; (* Execute -> Completing *)
            16: tillstand := 17; (* Completing -> Complete *)
            10: tillstand := 11; (* Holding -> Held *)
            12: tillstand := 6;  (* Unholding -> Execute *)
            13: tillstand := 5;  (* Suspending -> Suspended *)
            14: tillstand := 6;  (* Unsuspending -> Execute *)
            7:  tillstand := 2;  (* Stopping -> Stopped *)
            8:  tillstand := 9;  (* Aborting -> Aborted *)
            1:  tillstand := 2;  (* Clearing -> Stopped *)
        END_CASE;
    END_IF;
END_IF;

ST200_PML_STATE := tillstand;
ST200_CNV_RUN := (tillstand = 6);
ST200_DIV_OPEN := (tillstand = 6) AND (ST200_HGT_MM > 120.0);
SYS_ALARM := (tillstand = 8) OR (tillstand = 9);

trigSc(CLK := ST200_PML_SC);

xOmradeOk := (ST200_HGT_MM >= 0.0) AND (ST200_HGT_MM <= 250.0);
xMaskinfel := (NOT EMG_OK) OR (NOT xOmradeOk);

kmd := ST200_PML_CMD;

IF xMaskinfel THEN
    (* Maskinfel har alltid foretrade och gar till ABORTING oavsett tillstand *)
    IF (tillstand <> 8) AND (tillstand <> 9) THEN
        tillstand := 8;
    END_IF;
ELSE
    (* Automatiska overgangar for verkande tillstand, styrda av State Complete *)
    CASE tillstand OF
        15: IF trigSc.Q THEN tillstand := 4;  END_IF; (* Resetting -> Idle *)
        3:  IF trigSc.Q THEN tillstand := 6;  END_IF; (* Starting -> Execute *)
        6:  IF trigSc.Q THEN tillstand := 16; END_IF; (* Execute -> Completing *)
        16: IF trigSc.Q THEN tillstand := 17; END_IF; (* Completing -> Complete *)
        10: IF trigSc.Q THEN tillstand := 11; END_IF; (* Holding -> Held *)
        12: IF trigSc.Q THEN tillstand := 6;  END_IF; (* Unholding -> Execute *)
        13: IF trigSc.Q THEN tillstand := 5;  END_IF; (* Suspending -> Suspended *)
        14: IF trigSc.Q THEN tillstand := 6;  END_IF; (* Unsuspending -> Execute *)
        7:  IF trigSc.Q THEN tillstand := 2;  END_IF; (* Stopping -> Stopped *)
        1:  IF trigSc.Q THEN tillstand := 2;  END_IF; (* Clearing -> Stopped *)
    ELSE
        ;
    END_CASE;

    (* Kommandobehandling, ogiltiga kommandon i aktuellt tillstand gor ingenting *)
    IF (kmd >= 1) AND (kmd <= 9) THEN
        CASE kmd OF
            1: (* Reset *)
                IF (tillstand = 2) OR (tillstand = 17) THEN
                    tillstand := 15;
                END_IF;
            2: (* Start *)
                IF tillstand = 4 THEN
                    tillstand := 3;
                END_IF;
            3: (* Stop, ogiltig i Stopping, Stopped, Aborting, Aborted, Clearing *)
                IF NOT (tillstand = 7 OR tillstand = 2 OR tillstand = 8 OR tillstand = 9 OR tillstand = 1) THEN
                    tillstand := 7;
                END_IF;
            4: (* Hold *)
                IF tillstand = 6 THEN
                    tillstand := 10;
                END_IF;
            5: (* Unhold *)
                IF tillstand = 11 THEN
                    tillstand := 12;
                END_IF;
            6: (* Suspend *)
                IF tillstand = 6 THEN
                    tillstand := 13;
                END_IF;
            7: (* Unsuspend *)
                IF tillstand = 5 THEN
                    tillstand := 14;
                END_IF;
            8: (* Abort, giltig i alla tillstand utom Aborting och Aborted, gar aldrig via genvag *)
                IF NOT (tillstand = 8 OR tillstand = 9) THEN
                    tillstand := 8;
                END_IF;
            9: (* Clear, enda vagen ut ur Aborted *)
                IF tillstand = 9 THEN
                    tillstand := 1;
                END_IF;
        END_CASE;
    END_IF;
END_IF;

ST200_PML_STATE := tillstand;
ST200_CNV_RUN := (tillstand = 6);
ST200_DIV_OPEN := (tillstand = 6) AND (ST200_HGT_MM > 120.0);
SYS_ALARM := (tillstand = 8) OR (tillstand = 9);

kmd := ST200_PML_CMD;

trigSc(CLK := ST200_PML_SC);

(* maskinfel: brutet EMG_OK eller hojd utanfor 0..250 mm *)
xOmradeOk := (ST200_HGT_MM >= 0.0) AND (ST200_HGT_MM <= 250.0);
IF (NOT EMG_OK) OR (NOT xOmradeOk) THEN
    xMaskinfel := TRUE;
ELSE
    xMaskinfel := FALSE;
END_IF;

(* fel tar maskinen till ABORTING oavsett tillstand, utom om redan dar *)
IF xMaskinfel AND (tillstand <> 8) AND (tillstand <> 9) THEN
    tillstand := 8;
ELSE
    (* kommandohantering *)
    CASE kmd OF
        1: (* Reset, giltigt i Stopped och Complete *)
            IF (tillstand = 2) OR (tillstand = 17) THEN
                tillstand := 15;
            END_IF;
        2: (* Start, giltigt i Idle *)
            IF tillstand = 4 THEN
                tillstand := 3;
            END_IF;
        3: (* Stop, ogiltigt i Stopping, Stopped, Aborting, Aborted, Clearing *)
            IF (tillstand <> 7) AND (tillstand <> 2) AND (tillstand <> 8) AND (tillstand <> 9) AND (tillstand <> 1) THEN
                tillstand := 7;
            END_IF;
        4: (* Hold, giltigt i Execute *)
            IF tillstand = 6 THEN
                tillstand := 10;
            END_IF;
        5: (* Unhold, giltigt i Held *)
            IF tillstand = 11 THEN
                tillstand := 12;
            END_IF;
        6: (* Suspend, giltigt i Execute *)
            IF tillstand = 6 THEN
                tillstand := 13;
            END_IF;
        7: (* Unsuspend, giltigt i Suspended *)
            IF tillstand = 5 THEN
                tillstand := 14;
            END_IF;
        8: (* Abort, giltigt i alla tillstand utom Aborting och Aborted *)
            IF (tillstand <> 8) AND (tillstand <> 9) THEN
                tillstand := 8;
            END_IF;
        9: (* Clear, enda vagen ut ur Aborted *)
            IF tillstand = 9 THEN
                tillstand := 1;
            END_IF;
    END_CASE;

    (* State Complete: det verkande tillstandets arbete ar klart *)
    IF trigSc.Q THEN
        CASE tillstand OF
            15: tillstand := 4;   (* Resetting -> Idle *)
            3:  tillstand := 6;   (* Starting -> Execute *)
            6:  tillstand := 16;  (* Execute -> Completing *)
            16: tillstand := 17;  (* Completing -> Complete *)
            10: tillstand := 11;  (* Holding -> Held *)
            12: tillstand := 6;   (* Unholding -> Execute *)
            13: tillstand := 5;   (* Suspending -> Suspended *)
            14: tillstand := 6;   (* Unsuspending -> Execute *)
            7:  tillstand := 2;   (* Stopping -> Stopped *)
            8:  tillstand := 9;   (* Aborting -> Aborted *)
            1:  tillstand := 2;   (* Clearing -> Stopped *)
        END_CASE;
    END_IF;
END_IF;

(* utsignaler *)
ST200_PML_STATE := tillstand;
ST200_CNV_RUN := (tillstand = 6);
SYS_ALARM := (tillstand = 8) OR (tillstand = 9);

IF tillstand = 6 THEN
    ST200_DIV_OPEN := (ST200_HGT_MM > 120.0);
ELSE
    ST200_DIV_OPEN := FALSE;
END_IF;

(* --- Kvitteringslogik: larm och omstartskvittens nollstalls bara pa stigande *)
(* flank pa SYS_RESET, och bara nar EMG_OK och AIR_OK ar hoga.                *)
trigReset(CLK := SYS_RESET);
IF trigReset.Q AND EMG_OK AND AIR_OK THEN
    xLarm := FALSE;
    xKravOmstart := FALSE;
END_IF;

(* --- Givarfel: encodern ska ligga inom arbetsomradet 0..300 mm --- *)
IF (ST050_IDX_POS < 0.0) OR (ST050_IDX_POS > 300.0) THEN
    xLarm := TRUE;
END_IF;

(* --- Frigivning: sakerhets-PLC (EMG_OK) lases bara, ingen egen sakerhetslogik --- *)
xDriftsklar := EMG_OK AND AIR_OK AND SYS_AUTO AND (NOT xKravOmstart) AND (NOT xLarm);

(* --- Sekvens --- *)
IF xDriftsklar THEN
    CASE steg OF
        0:
            IF ST050_PRT_PRS THEN
                ST050_CLP_CLOSE := TRUE;
                steg := 1;
            END_IF;

        1:
            IF ST050_CLP_CLOSED THEN
                ST050_IDX_START := TRUE;
                steg := 2;
            END_IF;

        2:
            IF ST050_IDX_DONE THEN
                ST050_IDX_START := FALSE;
                ST050_CLP_CLOSE := FALSE;
                steg := 0;
            END_IF;

        ELSE
            steg := 0;
    END_CASE;
ELSE
    (* stationen far inte ga: kommendon faller, sekvensen startar om fran borjan *)
    ST050_IDX_START := FALSE;
    ST050_CLP_CLOSE := FALSE;
    steg := 0;
END_IF;

(* --- Forregling: ST050_IDX_START far aldrig sta hog nar klamman inte haller --- *)
IF ST050_IDX_START AND (NOT ST050_CLP_CLOSED) THEN
    ST050_IDX_START := FALSE;
    xLarm := TRUE;
END_IF;

(* --- Tidsovervakning pa indexrorelsen, 2,0 s --- *)
tmrIndex(IN := ST050_IDX_START, PT := T#2.0S);
IF tmrIndex.Q AND (NOT ST050_IDX_DONE) THEN
    xLarm := TRUE;
END_IF;

(* --- Utmatningsband gar sa lange stationen ar driftsklar --- *)
ST050_CNV_RUN := xDriftsklar;

(* --- Larmet ar latchat: staller inte av sig sjalvt, bara via kvitterad flank --- *)
SYS_ALARM := xLarm;

trigReset(CLK := SYS_RESET);
IF trigReset.Q AND EMG_OK AND AIR_OK THEN
    xLarm := FALSE;
    xKravOmstart := FALSE;
END_IF;

xDriftsklar := EMG_OK AND AIR_OK AND SYS_AUTO AND NOT xKravOmstart AND NOT xLarm;

(* Givarfel: matarlaget utanfor arbetsomradet 0..300 mm *)
IF ST050_IDX_POS < 0.0 OR ST050_IDX_POS > 300.0 THEN
    xLarm := TRUE;
END_IF;

(* Forregling: index far aldrig kora med oppen klamma *)
IF steg = 2 AND NOT ST050_CLP_CLOSED THEN
    xLarm := TRUE;
END_IF;

(* Tidsovervakning av indexrorelsen, 2,0 s *)
tmrIndex(IN := (steg = 2), PT := T#2s);
IF tmrIndex.Q THEN
    xLarm := TRUE;
END_IF;

IF xLarm THEN
    steg := 0;
END_IF;

CASE steg OF
    0:
        IF xDriftsklar AND ST050_PRT_PRS THEN
            steg := 1;
        END_IF;
    1:
        IF xDriftsklar AND ST050_CLP_CLOSED THEN
            steg := 2;
        END_IF;
    2:
        IF ST050_IDX_DONE THEN
            steg := 0;
        END_IF;
    ELSE
        steg := 0;
END_CASE;

ST050_CNV_RUN := xDriftsklar;
ST050_CLP_CLOSE := xDriftsklar AND (steg = 1 OR steg = 2);
ST050_IDX_START := xDriftsklar AND (steg = 2) AND ST050_CLP_CLOSED;
SYS_ALARM := xLarm;

(* stigande flank pa SYS_RESET, anvands for kvittering *)
trigReset(CLK := SYS_RESET);

(* kvittering av omstartskrav och larm, endast pa flanken och bara med EMG_OK och AIR_OK hoga *)
IF trigReset.Q AND EMG_OK AND AIR_OK THEN
    xKravOmstart := FALSE;
    xLarm := FALSE;
END_IF;

(* givarfel: matarlaget utanfor arbetsomradet 0..300 mm *)
IF ST050_IDX_POS < 0.0 OR ST050_IDX_POS > 300.0 THEN
    xLarm := TRUE;
END_IF;

(* forregling: index far aldrig sta hogt om klamman inte haller *)
IF ST050_IDX_START AND NOT ST050_CLP_CLOSED THEN
    xLarm := TRUE;
END_IF;

(* tidsovervakning av indexrorelsen, 2,0 s fran start till klart *)
tmrIndex(IN := ST050_IDX_START, PT := T#2s);
IF tmrIndex.Q AND NOT ST050_IDX_DONE THEN
    xLarm := TRUE;
END_IF;

(* samlingslarmet ar latchat: det star kvar tills en kvitterad flank *)
SYS_ALARM := xLarm;

(* driftsvillkor: nodstopp och luft last, automatlage, ingen kvittering ute, inget larm *)
xDriftsklar := EMG_OK AND AIR_OK AND SYS_AUTO AND NOT xKravOmstart AND NOT xLarm;

(* utmatningsbandet foljer driftvillkoret och stannar direkt vid larm *)
ST050_CNV_RUN := xDriftsklar;

IF NOT xDriftsklar THEN
    (* stationen stoppas: nollstall sekvensen och kommandona *)
    steg := 0;
    ST050_CLP_CLOSE := FALSE;
    ST050_IDX_START := FALSE;
ELSE
    CASE steg OF
        0: (* vantar pa att en detalj ligger pa plats *)
            IF ST050_PRT_PRS THEN
                ST050_CLP_CLOSE := TRUE;
                steg := 1;
            END_IF;

        1: (* vantar pa att klamman bekraftar stangt lage *)
            IF ST050_CLP_CLOSED THEN
                ST050_IDX_START := TRUE;
                steg := 2;
            END_IF;

        2: (* vantar pa att indexrorelsen ar klar *)
            IF ST050_IDX_DONE THEN
                ST050_IDX_START := FALSE;
                ST050_CLP_CLOSE := FALSE;
                steg := 0;
            END_IF;
    END_CASE;
END_IF;

trigReset(CLK := SYS_RESET);

IF NOT EMG_OK THEN
    xKravOmstart := TRUE;
END_IF;

IF trigReset.Q AND EMG_OK AND AIR_OK THEN
    xKravOmstart := FALSE;
    xLarm := FALSE;
END_IF;

(* Givarfel: encodern utanfor arbetsomradet *)
IF (ST050_IDX_POS < 0.0) OR (ST050_IDX_POS > 300.0) THEN
    xLarm := TRUE;
END_IF;

(* Forregling: index far aldrig kommenderas med oppen klamma *)
IF ST050_IDX_START AND NOT ST050_CLP_CLOSED THEN
    xLarm := TRUE;
END_IF;

(* Tidsovervakning av indexrorelsen *)
tmrIndex(IN := (steg = 2), PT := T#2.0S);
IF tmrIndex.Q THEN
    xLarm := TRUE;
END_IF;

xDriftsklar := EMG_OK AND AIR_OK AND SYS_AUTO AND NOT xKravOmstart;

IF xLarm THEN
    ST050_IDX_START := FALSE;
    ST050_CLP_CLOSE := FALSE;
    ST050_CNV_RUN := FALSE;
    steg := 0;
ELSIF NOT xDriftsklar THEN
    ST050_CNV_RUN := FALSE;
ELSE
    ST050_CNV_RUN := TRUE;
    CASE steg OF
        0:
            IF ST050_PRT_PRS THEN
                ST050_CLP_CLOSE := TRUE;
                steg := 1;
            END_IF;
        1:
            IF ST050_CLP_CLOSED THEN
                ST050_IDX_START := TRUE;
                steg := 2;
            END_IF;
        2:
            IF ST050_IDX_DONE THEN
                ST050_IDX_START := FALSE;
                ST050_CLP_CLOSE := FALSE;
                steg := 0;
            END_IF;
    END_CASE;
END_IF;

SYS_ALARM := xLarm;
